CREATE TYPE seat_status AS ENUM ('AVAILABLE', 'LOCKED', 'BOOKED', 'CANCELLED');
CREATE TABLE IF NOT EXISTS schedule_inventories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), schedule_id text NOT NULL UNIQUE, train_id text NOT NULL, train_number text NOT NULL, train_name text NOT NULL, departure_date date NOT NULL, total_seats integer NOT NULL, available integer NOT NULL, locked integer NOT NULL DEFAULT 0, booked integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'ACTIVE', version integer NOT NULL DEFAULT 0, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS seat_inventories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), schedule_inventory_id uuid NOT NULL REFERENCES schedule_inventories(id) ON DELETE CASCADE, schedule_id text NOT NULL, seat_id text NOT NULL, seat_number integer NOT NULL, seat_type text NOT NULL, price real NOT NULL, status seat_status NOT NULL DEFAULT 'AVAILABLE', locked_by text, locked_at timestamp, lock_expires_at timestamp, booking_id text, version integer NOT NULL DEFAULT 0, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), CONSTRAINT seat_inventories_schedule_seat_unique UNIQUE(schedule_id, seat_id), CONSTRAINT seat_inventories_schedule_number_unique UNIQUE(schedule_id, seat_number));
CREATE TABLE IF NOT EXISTS route_stops (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), schedule_id text NOT NULL, station_id text NOT NULL, station_name text NOT NULL, station_code text NOT NULL, sequence_number integer NOT NULL, CONSTRAINT route_stops_schedule_station_unique UNIQUE(schedule_id, station_id), CONSTRAINT route_stops_schedule_sequence_unique UNIQUE(schedule_id, sequence_number));
CREATE TABLE IF NOT EXISTS seat_segment_locks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), schedule_id text NOT NULL, seat_id text NOT NULL, from_seq integer NOT NULL, to_seq integer NOT NULL, status seat_status NOT NULL DEFAULT 'LOCKED', locked_by text, locked_at timestamp, lock_expires_at timestamp, booking_id text, version integer NOT NULL DEFAULT 0, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_key text NOT NULL UNIQUE, processed_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic text NOT NULL, key text, value jsonb NOT NULL, headers jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'PENDING', retry_count integer NOT NULL DEFAULT 0, max_retries integer NOT NULL DEFAULT 5, created_at timestamp NOT NULL DEFAULT now(), processed_at timestamp, last_error text);
